```javascript
import * as THREE from 'three/webgpu';
import {
  texture,
  uv,
  positionLocal,
  normalLocal,
  float,
  vec3,
  uniform,
  mix,
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'home-quote-panel';

  const pos = config.position || [-2.5, -1.1, 0];
  const rot = config.rotation || [0, 0, 0];
  const scl = config.scale || [1, 1, 1];
  group.position.set(pos[0], pos[1], pos[2]);
  group.rotation.set(rot[0], rot[1], rot[2]);
  group.scale.set(scl[0], scl[1], scl[2]);

  const imageUrl = '/prism-mock/home/nodes/parallax-stack.png';
  const depthUrl = '/prism-mock/home/nodes/parallax-stack.depth.png';

  const colorMap = ctx.textureLoader.load(imageUrl);
  colorMap.colorSpace = THREE.SRGBColorSpace;
  const depthMap = ctx.textureLoader.load(depthUrl);

  const aspect = 512 / 320;
  const width = 2.4;
  const height = width / aspect;

  const geometry = new THREE.PlaneGeometry(width, height, 64, 64);

  const displacementStrength = uniform(0.12);
  const colorTex = texture(colorMap, uv());
  const depthTex = texture(depthMap, uv());

  const displaced = positionLocal.add(
    normalLocal.mul(depthTex.r.sub(0.5).mul(displacementStrength))
  );

  const material = new THREE.MeshPhysicalNodeMaterial();
  material.colorNode = colorTex;
  material.positionNode = displaced;
  material.roughness = 0.55;
  material.metalness = 0.5;
  material.clearcoat = 0.2;
  material.clearcoatRoughness = 0.4;
  material.anisotropy = 0.6;

  const mesh = new THREE.Mesh(geometry, material);
  mesh.name = 'home-quote-panel-mesh';
  group.add(mesh);

  // accent rim light
  const rimLight = new THREE.PointLight(0xff2a38, 0.8, 4, 2);
  rimLight.position.set(0.6, 0.4, 1.2);
  group.add(rimLight);

  // quote + attribution text via fontAtlas
  const quoteText = ctx.fontAtlas.createText({
    text: '"The precision is the poetry."',
    font: 'display',
    weight: 400,
    size: 0.2,
    color: config.colors?.paper || '#e8ecf2',
    maxWidth: width * 0.85,
    align: 'left',
  });
  quoteText.position.set(-width / 2 + 0.25, height / 2 - 0.4, 0.02);
  group.add(quoteText);

  const attribText = ctx.fontAtlas.createText({
    text: '— Atelier Client',
    font: 'text',
    weight: 700,
    size: 0.13,
    color: config.colors?.accent || '#ff2a38',
    maxWidth: width * 0.7,
    align: 'left',
  });
  attribText.position.set(-width / 2 + 0.25, -height / 2 + 0.3, 0.02);
  group.add(attribText);

  // apply cinematic primitives
  ctx.primitives['parallax-scroll'](group, { intensity: 0.4, trigger: 'scroll' });
  ctx.primitives['depth-rotate'](mesh, { maxDeg: 8, trigger: 'hover' });

  // hover: rise-in subtle
  const baseY = group.position.y;
  const hoverTl = gsap.timeline({ paused: true });
  hoverTl.to(group.position, {
    y: baseY + 0.15,
    duration: 0.7,
    ease: 'power3.out',
  });

  const onPointerOver = () => {
    hoverTl.play();
  };
  const onPointerOut = () => {
    hoverTl.reverse();
  };
  const onClick = () => {
    gsap.timeline()
      .to(group.scale, { x: scl[0] * 0.97, y: scl[1] * 0.97, z: scl[2] * 0.97, duration: 0.12, ease: 'back.out' })
      .to(group.scale, { x: scl[0], y: scl[1], z: scl[2], duration: 0.3, ease: 'power2.out' });

    if (group.userData.emit) {
      group.userData.emit('hub-home.select', { source: 'home-quote-panel' });
    }
  };

  group.userData.handlers = {
    pointerover: onPointerOver,
    pointerout: onPointerOut,
    click: onClick,
  };

  // entrance: weighted-settle
  group.scale.set(scl[0] * 0.001, scl[1] * 0.001, scl[2] * 0.001);
  const entranceTl = gsap.timeline();
  entranceTl.to(group.scale, {
    x: scl[0] * 1.04,
    y: scl[1] * 1.04,
    z: scl[2] * 1.04,
    duration: 0.55,
    ease: 'power4.out',
  }).to(group.scale, {
    x: scl[0],
    y: scl[1],
    z: scl[2],
    duration: 0.35,
    ease: 'power4.out',
  });

  group.userData.cleanup = () => {
    hoverTl.kill();
    entranceTl.kill();
    geometry.dispose();
    material.dispose();
    colorMap.dispose();
    depthMap.dispose();
    rimLight.dispose?.();
    if (quoteText.userData?.cleanup) quoteText.userData.cleanup();
    if (attribText.userData?.cleanup) attribText.userData.cleanup();
    group.userData.handlers = {};
  };

  return group;
}
